node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Get the order
const order = db.prepare(\"SELECT * FROM orders WHERE order_id = ?\").get('#W' + 'ORD-F15D7C'.replace('ORD-',''));
console.log('Order (exact match #W...):', order);

// Try different patterns
const orders = db.prepare(\"SELECT * FROM orders WHERE order_id LIKE '%F15D7C%'\").all();
console.log('Orders matching F15D7C:', orders);

// Check column names
const cols = db.prepare('PRAGMA table_info(orders)').all();
console.log('Orders columns:', cols.map(c=>c.name));
"

