node -e "
const db = require('better-sqlite3')('/workspace/world.db');

const productIds = ['PROD-3E35A7', 'PROD-4ED2E3', 'PROD-39F904', 'PROD-FA0948'];

// Check products table columns
const cols = db.prepare('PRAGMA table_info(products)').all();
console.log('Products columns:', cols.map(c=>c.name));

for (const pid of productIds) {
  const product = db.prepare('SELECT * FROM products WHERE product_id = ?').get(pid);
  console.log('\n=== PRODUCT: ' + pid + ' ===');
  console.log(JSON.stringify(product, null, 2));
}
"

